<?php
if(!defined('ABSPATH')){exit;}
final class AICS_Yoast_SEO_Adapter extends AICS_Abstract_Postmeta_SEO_Adapter{private const META=array('seo_title'=>'_yoast_wpseo_title','meta_description'=>'_yoast_wpseo_metadesc','focus_keyword'=>'_yoast_wpseo_focuskw');protected function metadata_keys():array{return self::META;}public function get_key():string{return 'yoast';}public function get_label():string{return 'Yoast SEO';}public function is_available():bool{return defined('WPSEO_VERSION')||class_exists('WPSEO_Options');}public function get_version():string{return defined('WPSEO_VERSION')?(string)WPSEO_VERSION:'';}public function get_compatibility_status():string{return $this->is_available()?'compatible':'unavailable';}public function refresh_post_seo_data(int $post_id){clean_post_cache($post_id);do_action('wpseo_save_compare_data',$post_id);return true;}}
